function rootDraw(A){return eyeV(A,(c,W,st)=>{const L=st.cells;c.lineWidth=2;L.forEach(z=>{const{x,y,w,h,ph}=z;c.fillStyle='#f6e7e9';c.strokeStyle='#b06a7a';c.beginPath();c.rect(x,y,w,h);c.fill();c.stroke();const cx=x+w/2,cy=y+h/2;c.fillStyle='#8b1d3f';c.strokeStyle='#8b1d3f';
  if(ph===0){c.globalAlpha=.75;c.beginPath();c.ellipse(cx,cy,w*.24,h*.27,0,0,7);c.fill();c.globalAlpha=1;c.fillStyle='#4a0d22';c.beginPath();c.arc(cx+3,cy-2,3,0,7);c.fill()}
  if(ph===1){c.lineWidth=2.2;c.beginPath();c.ellipse(cx,cy,w*.27,h*.3,0,0,7);c.stroke();for(let i=0;i<9;i++){c.beginPath();c.moveTo(cx-w*.2+i*w*.05,cy-h*.2);c.quadraticCurveTo(cx+(i%3-1)*8,cy,cx-w*.15+i*w*.04,cy+h*.2);c.stroke()}}
  if(ph===2){for(let i=0;i<8;i++){c.fillRect(cx-3,cy-h*.32+i*h*.08,7,h*.06)}c.strokeStyle='rgba(139,29,63,.3)';c.lineWidth=1;for(let i=0;i<5;i++){c.beginPath();c.moveTo(x+4,cy);c.lineTo(cx,cy-h*.3+i*h*.15);c.lineTo(x+w-4,cy);c.stroke()}}
  if(ph===3){[-1,1].forEach(s=>{for(let i=0;i<7;i++){c.save();c.translate(cx+s*w*.26,cy-h*.27+i*h*.09);c.rotate(s*.6);c.fillRect(-6,-2,12,4);c.restore()}})}
  if(ph===4){[-1,1].forEach(s=>{c.globalAlpha=.85;c.beginPath();c.ellipse(cx+s*w*.27,cy,w*.15,h*.22,0,0,7);c.fill()});c.globalAlpha=1;c.strokeStyle='#b06a7a';c.lineWidth=2;c.setLineDash([4,3]);c.beginPath();c.moveTo(cx,y+3);c.lineTo(cx,y+h-3);c.stroke();c.setLineDash([])}})},{bg:'#fbf3f4'})}
