function leafDraw(A){return eyeV(A,(c,W,st,R)=>{const c4=st.slide==='c4';c.fillStyle='#e9f5d9';c.fillRect(0,0,W,W);
 c.fillStyle='#dfeec6';c.strokeStyle='#5a7d2a';c.lineWidth=2;for(let x=0;x<W;x+=26){c.beginPath();c.rect(x,30,26,22);c.fill();c.stroke();c.beginPath();c.rect(x,370,26,22);c.fill();c.stroke()}
 const B=[[110,210],[300,210]];
 const cell=(x,y,r,col,chl)=>{c.fillStyle=col;c.strokeStyle='#5a7d2a';c.lineWidth=1.6;c.beginPath();c.arc(x,y,r,0,7);c.fill();c.stroke();for(let i=0;i<chl;i++){const a=i/chl*6.28;c.fillStyle='#2f8a2f';c.beginPath();c.ellipse(x+Math.cos(a)*r*.62,y+Math.sin(a)*r*.62,r*.2,r*.12,a,0,7);c.fill()}};
 if(!c4){for(let i=0;i<70;i++){const x=20+R()*380,y=70+R()*290;if(B.some(b=>Math.hypot(x-b[0],y-b[1])<55))continue;cell(x,y,16+R()*5,'#cfe8a6',6)}B.forEach(([x,y])=>{for(let i=0;i<12;i++){const a=i/12*6.28;cell(x+Math.cos(a)*38,y+Math.sin(a)*38,10,'#f4f8e8',0)}c.fillStyle='#c9b98a';c.beginPath();c.arc(x,y,26,0,7);c.fill();c.fillStyle='#7c6f3a';[[-8,-6],[8,-6],[0,8]].forEach(([dx,dy])=>{c.beginPath();c.arc(x+dx,y+dy,6,0,7);c.fill()})})}
 else{B.forEach(([x,y])=>{for(let i=0;i<14;i++){const a=i/14*6.28;c.save();c.translate(x+Math.cos(a)*70,y+Math.sin(a)*70);c.rotate(a);c.fillStyle='#d4ecac';c.strokeStyle='#5a7d2a';c.beginPath();c.ellipse(0,0,22,10,0,0,7);c.fill();c.stroke();c.fillStyle='#3aa13a';for(let k=-2;k<=2;k++){c.beginPath();c.ellipse(k*7,0,3,2,0,0,7);c.fill()}c.restore()}
  for(let i=0;i<11;i++){const a=i/11*6.28;cell(x+Math.cos(a)*40,y+Math.sin(a)*40,14,'#7fbf4f',10)}c.fillStyle='#c9b98a';c.beginPath();c.arc(x,y,25,0,7);c.fill();c.fillStyle='#7c6f3a';[[-8,-6],[8,-6],[0,8]].forEach(([dx,dy])=>{c.beginPath();c.arc(x+dx,y+dy,6,0,7);c.fill()})})}},{bg:'#e9f5d9'})}
