/* 11-10 Микрометр */
function calDraw(A){return eyeV(A,(c,W,st)=>{if(st.slide==='stm'){c.strokeStyle='#111';c.fillStyle='#111';c.lineWidth=2;const x0=60,u=12;c.beginPath();c.moveTo(x0-40,236);c.lineTo(x0+30*u,236);c.stroke();for(let i=0;i<=28;i++){const L=i%10===0?26:i%5===0?18:12;c.beginPath();c.moveTo(x0+i*u,236);c.lineTo(x0+i*u,236+L);c.stroke()}c.font='600 12px sans-serif';c.fillText('0,01 мм',x0+150,280)}
 else{const R=rng(4);[[96,210,36,'#c7d2fe'],[300,140,40,'#c7d2fe'],[260,300,34,'#c7d2fe']].forEach(([x,y,r,col],j)=>{c.fillStyle='rgba(165,180,252,.55)';c.strokeStyle='#4338ca';c.lineWidth=2;c.beginPath();for(let i=0;i<=10;i++){const a=i/10*6.28;const rr=r*(.9+R()*.2);c[i?'lineTo':'moveTo'](x+Math.cos(a)*rr,y+Math.sin(a)*rr)}c.closePath();c.fill();c.stroke();c.fillStyle='#312e81';c.beginPath();c.arc(x+3,y,7,0,7);c.fill()})}},{bg:'#f8fafc'})}
function grat(c,W,st){if(!st.grat)return;c.strokeStyle='#dc2626';c.fillStyle='#dc2626';c.lineWidth=1.6;const x0=60,u=3;c.beginPath();c.moveTo(x0,210);c.lineTo(x0+100*u,210);c.stroke();for(let i=0;i<=100;i++){const L=i%10===0?16:i%5===0?10:6;c.beginPath();c.moveTo(x0+i*u,210);c.lineTo(x0+i*u,210-L);c.stroke();if(i%10===0){c.font='700 11px sans-serif';c.textAlign='center';c.fillText(i,x0+i*u,188)}}}
