/* 11-13 Экожүйе статистикасы */
const SP=[['Бақбақ',0xfacc15],['Жолжелкен',0x4d7c0f],['Беде',0xf5f5f4],['Түймедақ',0xffffff]];
function meadow(A){const R=rng(21);const pts=[];for(let i=0;i<520;i++){const s=R()<.32?0:R()<.4?1:R()<.6?2:3;let x=(R()-.5)*5.6,z=(R()-.5)*3.2;if(s===0&&R()<.5){x=x*.5+1;}pts.push([x,z,s])}return pts}
const QD=[[-2,-1],[-.8,.6],[.6,-.7],[1.6,.9],[2.2,-.4]];
const L_eco={id:'ecostat',ic:'🌼',n:'Талдаудың статистикалық әдістерін қолдану арқылы өз өңірінің экожүйесінің жағдайын анықтау',gr:'11-сынып',goal:'Шалғын учаскесінде 1 м² сынама алаңдарын (квадраттарды) салып, түрлерді санау, орташа тығыздықты, стандартты ауытқуды және Симпсон әралуандық индексін есептеу.',eq:['Шалғын учаскесінің моделі (20 × 12 м)','Квадрат 1 × 1 м','Анықтағыш','Калькулятор'],view:[0,1,.3,7.5,[0,1,.8]],
 setup(A){const g=new A.THREE.Group();const base=A.mesh(new A.THREE.BoxGeometry(6,.08,3.6),A.M(0x5f9f3a,{roughness:.9}));g.add(base);const P=meadow(A);A.LB.st={P,rows:[],qi:0};
  const geo=[new A.THREE.SphereGeometry(.045,8,6),new A.THREE.ConeGeometry(.05,.12,6),new A.THREE.SphereGeometry(.035,8,6),new A.THREE.SphereGeometry(.04,8,6)];SP.forEach(([n,c],s)=>{const L=P.filter(p=>p[2]===s);const im=new A.THREE.InstancedMesh(geo[s],A.M(c,{roughness:.6}),L.length);const m4=new A.THREE.Matrix4();L.forEach((p,i)=>{m4.makeTranslation(p[0],.09,p[1]);im.setMatrixAt(i,m4)});g.add(im)});
  const gr=new A.THREE.InstancedMesh(new A.THREE.ConeGeometry(.012,.12,4),A.M(0x3f7f26),1500);const R=rng(5);const m4=new A.THREE.Matrix4();for(let i=0;i<1500;i++){m4.makeTranslation((R()-.5)*5.8,.1,(R()-.5)*3.4);gr.setMatrixAt(i,m4)}g.add(gr);A.add('mead',{obj:g},null,[0,.04,.4]);
  const q=new A.THREE.Group();const fm=A.M(0xef4444);[[0,.3,.6,.03],[0,-.3,.6,.03],[.3,0,.03,.6],[-.3,0,.03,.6]].forEach(([x,z,w,d])=>{const b=A.mesh(new A.THREE.BoxGeometry(w,.04,d),fm);b.position.set(x,.14,z);q.add(b)});A.add('quad',{obj:q},'Квадрат 1 м²',[4,.02,2.6])},
 steps:[...QD.map((d,i)=>({t:'click',o:'quad',text:`Квадратты кездейсоқ нүктеге таста (${i+1}/5) және ішіндегі өсімдіктерді сана`,run:async A=>{const q=A.LB.O.quad.obj;const m=A.LB.O.mead.obj.position;await A.moveTo(q,A.V3(m.x+d[0],.02,m.z+d[1]),.8,1);const c=[0,0,0,0];A.LB.st.P.forEach(p=>{if(Math.abs(p[0]-d[0])<.3&&Math.abs(p[1]-d[1])<.3)c[p[2]]++});A.LB.st.rows.push(c);
  A.data(tbl(['Квадрат',...SP.map(s=>s[0])],A.LB.st.rows.map((r,k)=>[k+1,...r])));if(i===0)A.look(m.x,.3,m.z,4.4,[0,1,.5])}})),
 {t:'input',text:'Бақбақтың орташа тығыздығын есепте: x̄ = Σx / n (дана/м²)',ans:A=>A.LB.st.rows.reduce((a,r)=>a+r[0],0)/5,tol:.05,unit:'дана/м²'},
 {t:'input',text:'Бақбақ санының стандартты ауытқуын есепте: s = √(Σ(x − x̄)² / (n − 1)) (екі ондық)',ans:A=>{const x=A.LB.st.rows.map(r=>r[0]),m=x.reduce((a,b)=>a+b)/5;return Math.sqrt(x.reduce((a,b)=>a+(b-m)**2,0)/4)},tol:.06},
 {t:'wait',text:'Барлық квадраттардағы әр түрдің жалпы санын есепте',run:async A=>{const T=[0,1,2,3].map(s=>A.LB.st.rows.reduce((a,r)=>a+r[s],0));A.LB.st.T=T;const N=T.reduce((a,b)=>a+b);A.data(tbl(['Түр',...SP.map(s=>s[0]),'N'],[['n',...T,N],['n(n−1)',...T.map(n=>n*(n-1)),'']]));await A.wait(.6)}},
 {t:'input',text:'Симпсон әралуандық индексін есепте: D = 1 − Σn(n−1) / N(N−1) (екі ондық)',ans:A=>{const T=A.LB.st.T,N=T.reduce((a,b)=>a+b);return 1-T.reduce((a,n)=>a+n*(n-1),0)/(N*(N-1))},tol:.02},
 {t:'choice',text:'D мәні 1-ге жақын болса, экожүйе туралы не айтуға болады?',options:['Әралуандық төмен, бір түр басым','Әралуандық жоғары, экожүйе тұрақты','Экожүйе ластанған','Мәліметтер жеткіліксіз'],correct:1},
 {t:'choice',text:'Неліктен квадраттар кездейсоқ тасталады?',options:['Жылдам болу үшін','Іріктеменің біржақтылығын (субъективтілікті) болдырмау үшін','Өсімдіктерді таптамау үшін','Әдемі болу үшін'],correct:1}],
 result:A=>{const T=A.LB.st.T||[0,0,0,0],N=T.reduce((a,b)=>a+b,0);const D=N>1?1-T.reduce((a,n)=>a+n*(n-1),0)/(N*(N-1)):0;const x=A.LB.st.rows.map(r=>r[0]);const m=x.reduce((a,b)=>a+b,0)/5;return tbl(['Квадрат',...SP.map(s=>s[0])],A.LB.st.rows.map((r,k)=>[k+1,...r]))+`<p class="muted">Бақбақтың орташа тығыздығы: <b>${r1(m,1)} дана/м²</b>; Симпсон индексі D = <b>${r1(D,2)}</b></p>`},
 obs:A=>{const T=A.LB.st.T||[];return 'квадраттардағы түрлер саны: '+A.LB.st.rows.map((r,i)=>`${i+1}-квадрат: ${r.join('/')}`).join('; ')+`; жалпы саны (бақбақ/жолжелкен/беде/түймедақ): ${T.join('/')}`}};

